from pathlib import Path
s=Path('astra-remaining-improvements/stage/b415b13a50ee');p=s/'tests/browser/interlude.spec.js';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(r'''
import { test, expect, chromium } from '@playwright/test';
import { fileURLToPath } from 'node:url';
import { mkdirSync } from 'node:fs';
import { join } from 'node:path';
const root=fileURLToPath(new URL('../../',import.meta.url));
const messageView=page=>page.getByRole('button',{name:'My message',exact:true}).click();
async function createPreset(page,title='Water',message='Take a sip') { await messageView(page);await page.getByLabel('Title',{exact:true}).fill(title);await page.getByLabel('Saved message text',{exact:true}).fill(message);await page.getByRole('button',{name:'Create saved message',exact:true}).click();await expect(page.getByRole('heading',{name:title,exact:true})).toBeVisible(); }
test('timer settings and literal reminder persist across reload',async({page})=>{
 await page.goto('/');await expect(page.locator('#countdown')).toHaveText('60:00');await page.getByRole('button',{name:'Start focus',exact:true}).click();await page.getByRole('button',{name:'Pause timer',exact:true}).click();await page.reload();await expect(page.getByRole('button',{name:/Resume timer|Start focus/,exact:true})).toBeVisible();await page.getByRole('button',{name:'Reset timer',exact:true}).click();
 await page.getByRole('button',{name:'Settings',exact:true}).click();await page.getByRole('button',{name:'Pomodoro',exact:false}).click();await page.getByRole('button',{name:'Save settings',exact:true}).click();await expect(page.locator('#toast')).toContainText('saved');await messageView(page);await page.getByLabel('A NOTE TO YOURSELF').fill('Drink water. <b>Just text.</b>');await page.getByRole('button',{name:'Save message',exact:true}).click();await expect(page.locator('#toast')).toHaveText('Your message is saved');await page.reload();await expect(page.locator('#countdown')).toHaveText('25:00');await expect(page.locator('#preview-message')).toHaveText('Drink water. <b>Just text.</b>');await expect(page.locator('#preview-message b')).toHaveCount(0);
});
test('saved messages create update use and delete without removing the active reminder',async({page})=>{
 await page.goto('/');await createPreset(page);await page.reload();await messageView(page);await page.getByRole('button',{name:'Edit Water',exact:true}).click();await page.getByLabel('Title',{exact:true}).fill('Hydrate');await page.getByLabel('Saved message text',{exact:true}).fill('A glass of water');await page.getByRole('button',{name:'Update saved message',exact:true}).click();await expect(page.getByRole('heading',{name:'Hydrate',exact:true})).toBeVisible();
 await page.getByRole('button',{name:'Use Hydrate',exact:true}).click();await expect(page.getByLabel('A NOTE TO YOURSELF')).toHaveValue('A glass of water');await page.getByRole('button',{name:'Save message',exact:true}).click();await expect(page.locator('#toast')).toHaveText('Your message is saved');page.once('dialog',d=>d.dismiss());await page.getByRole('button',{name:'Delete Hydrate',exact:true}).click();await expect(page.getByRole('heading',{name:'Hydrate',exact:true})).toBeVisible();page.once('dialog',d=>d.accept());await page.getByRole('button',{name:'Delete Hydrate',exact:true}).click();await expect(page.getByRole('heading',{name:'Hydrate',exact:true})).toHaveCount(0);await page.reload();await expect(page.locator('#preview-message')).toHaveText('A glass of water');
});
test('stale reminder form keeps its proposal after another tab saves',async({page,context})=>{
 await page.goto('/');const other=await context.newPage();await other.goto('/');await messageView(page);await messageView(other);await other.getByLabel('A NOTE TO YOURSELF').fill('Older proposal');await page.getByLabel('A NOTE TO YOURSELF').fill('Winning reminder');await page.getByRole('button',{name:'Save message',exact:true}).click();await expect(page.locator('#toast')).toHaveText('Your message is saved');await other.getByRole('button',{name:'Save message',exact:true}).click();await expect(other.locator('#toast')).toContainText('changed elsewhere');await expect(other.getByLabel('A NOTE TO YOURSELF')).toHaveValue('Older proposal');expect(await other.evaluate(()=>JSON.parse(localStorage.getItem('interlude-v1')).settings.message)).toBe('Winning reminder');await other.close();
});
test('stale saved-message edit conflicts instead of replacing a newer revision',async({page,context})=>{
 await page.goto('/');await createPreset(page);const other=await context.newPage();await other.goto('/');await messageView(other);await other.getByRole('button',{name:'Edit Water',exact:true}).click();await other.getByLabel('Saved message text',{exact:true}).fill('Stale library edit');await page.getByRole('button',{name:'Edit Water',exact:true}).click();await page.getByLabel('Saved message text',{exact:true}).fill('Accepted library edit');await page.getByRole('button',{name:'Update saved message',exact:true}).click();await expect(page.locator('#toast')).toHaveText('Saved message stored.');await other.getByRole('button',{name:'Update saved message',exact:true}).click();await expect(other.locator('#preset-error')).toContainText('changed elsewhere');await expect(other.getByLabel('Saved message text',{exact:true})).toHaveValue('Stale library edit');await other.close();
});
test('preview quota failure preserves active data and the reminder draft',async({page})=>{
 await page.addInitScript(()=>{Storage.prototype.setItem=function(){throw new DOMException('Quota exceeded','QuotaExceededError');};});await page.goto('/');const original=await page.locator('#preview-message').textContent();await messageView(page);await page.getByLabel('A NOTE TO YOURSELF').fill('Unsaved reminder');await page.getByRole('button',{name:'Save message',exact:true}).click();await expect(page.locator('#toast')).toContainText('Quota');await expect(page.getByLabel('A NOTE TO YOURSELF')).toHaveValue('Unsaved reminder');expect(await page.evaluate(()=>localStorage.getItem('interlude-v1'))).toBeNull();await page.getByRole('button',{name:'My timer',exact:true}).click();await expect(page.locator('#preview-message')).toHaveText(original);
});
test('corrupt preview data can be exported and requires explicit reset',async({page})=>{
 await page.addInitScript(()=>{if(!sessionStorage.getItem('fixture')){localStorage.setItem('interlude-v1','{broken');sessionStorage.setItem('fixture','1');}});await page.goto('/');await expect(page.locator('#toast')).toContainText('unreadable');await page.getByRole('button',{name:'Settings',exact:true}).click();const download=page.waitForEvent('download');await page.getByRole('button',{name:'Export local data',exact:true}).click();const stream=await(await download).createReadStream();let content='';for await(const chunk of stream)content+=chunk.toString();expect(content).toBe('{broken');page.once('dialog',d=>d.dismiss());await page.getByRole('button',{name:'Reset browser preview data',exact:true}).click();expect(await page.evaluate(()=>localStorage.getItem('interlude-v1'))).toBe('{broken');page.once('dialog',d=>d.accept());await page.getByRole('button',{name:'Reset browser preview data',exact:true}).click();await expect(page.getByRole('button',{name:'Start focus',exact:true})).toBeVisible();expect(await page.evaluate(()=>JSON.parse(localStorage.getItem('interlude-v1')).presets)).toEqual([]);
});
test('art selection upload and removal retain the existing image workflow',async({page})=>{
 await page.goto('/');await page.getByRole('button',{name:'Art collection',exact:false}).click();await page.getByRole('button',{name:/Bordighera/}).click();await expect(page.locator('#toast')).toHaveText('Artwork selected');await page.locator('#art-upload').setInputFiles(join(root,'extension/assets/garden.jpg'));await expect(page.getByRole('button',{name:/garden Personal collection/})).toBeVisible();await page.getByRole('button',{name:'Remove uploaded artwork',exact:true}).click();await expect(page.locator('#toast')).toHaveText('Uploaded artwork removed');await page.reload();expect(await page.evaluate(()=>JSON.parse(localStorage.getItem('interlude-v1')).settings.customArt)).toBeNull();
});
test('expired preview deadline transitions once and snooze retains the completed count',async({page})=>{
 await page.goto('/');await page.getByRole('button',{name:'Start focus',exact:true}).click();await page.evaluate(()=>{const data=JSON.parse(localStorage.getItem('interlude-v1'));data.state.deadline=Date.now()-1000;localStorage.setItem('interlude-v1',JSON.stringify(data));});await page.reload();await expect(page.getByRole('dialog',{name:'Art break'})).toBeVisible();await expect(page.locator('#completed-stat')).toHaveText('1');await page.getByRole('button',{name:'Snooze 5 min',exact:true}).click();await expect(page.getByRole('dialog',{name:'Art break'})).not.toBeVisible();expect(await page.evaluate(()=>JSON.parse(localStorage.getItem('interlude-v1')).state.completed)).toBe(1);
});
test('dashboard and message library fit desktop and narrow layouts',async({page})=>{
 const directory=process.env.INTERLUDE_RESULTS_DIR;if(directory)mkdirSync(directory,{recursive:true});await page.goto('/');await createPreset(page,'Small pause','Look beyond the screen.');
 for(const [label,width] of [['desktop',1440],['narrow',390]]){await page.setViewportSize({width,height:1000});for(const [view,button] of [['dashboard','My timer'],['messages','My message']]){await page.getByRole('button',{name:button,exact:true}).click();await page.locator(view==='dashboard'?'#preview-art':'#message-art').evaluate(img=>img.decode());expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);if(directory)await page.screenshot({path:join(directory,`${view}-${label}.png`),fullPage:true});}}
});
test('unpacked extension persists CRUD and reconciles real alarms and break windows',async()=>{
 const extensionPath=join(root,'extension');const context=await chromium.launchPersistentContext('',{channel:'chromium',headless:true,args:[`--disable-extensions-except=${extensionPath}`,`--load-extension=${extensionPath}`]});
 try{let worker=context.serviceWorkers()[0];if(!worker)worker=await context.waitForEvent('serviceworker');const id=new URL(worker.url()).host;const page=await context.newPage();await page.goto(`chrome-extension://${id}/index.html`);await expect(page.getByRole('button',{name:'Start focus',exact:true})).toBeVisible();await createPreset(page,'Extension reminder','Take a pause');await page.reload();await messageView(page);await expect(page.getByRole('heading',{name:'Extension reminder',exact:true})).toBeVisible();await page.getByRole('button',{name:'My timer',exact:true}).click();await page.getByRole('button',{name:'Start focus',exact:true}).click();
 const scheduled=await worker.evaluate(async()=>({data:await chrome.storage.local.get(['state','presets']),alarm:await chrome.alarms.get('interlude-timer')}));expect(scheduled.data.presets).toHaveLength(1);expect(scheduled.alarm.scheduledTime).toBe(scheduled.data.state.deadline);
 const result=await page.evaluate(()=>chrome.runtime.sendMessage({type:'command',command:'break'}));expect(result.warning).toBeUndefined();expect(result.state.phase).toBe('break');expect(result.state.breakWindow).not.toBeNull();const windowId=result.state.breakWindow;expect(await worker.evaluate(async id=>(await chrome.windows.get(id)).type,windowId)).toBe('popup');
 const snoozed=await page.evaluate(()=>chrome.runtime.sendMessage({type:'command',command:'snooze'}));expect(snoozed.state.phase).toBe('focus');expect(snoozed.state.total).toBe(300000);expect(snoozed.state.breakWindow).toBeNull();expect(await worker.evaluate(async id=>{try{await chrome.windows.get(id);return true;}catch{return false;}},windowId)).toBe(false);
 }finally{await context.close();}
});
'''.strip()+'\n',encoding='utf-8');print('Ten UI and actual extension workflows written')
